<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class SubscriptionPayment extends Model { protected $fillable=['subscription_account_id','subscription_id','subscription_plan_id','user_id','transaction_id','idempotency_key','kpp_reference','event_id','operation','billing_period','duration_months','amount_ht','tax_amount','amount','currency','snapshot','status','checkout_url','failure_reason','expires_at','paid_at','failed_at']; protected $casts=['snapshot'=>'array','duration_months'=>'integer','expires_at'=>'datetime','paid_at'=>'datetime','failed_at'=>'datetime']; public function plan(){return $this->belongsTo(SubscriptionPlan::class,'subscription_plan_id');} public function subscription(){return $this->belongsTo(Subscription::class,'subscription_id');} public function subscriptionAccount(){return $this->belongsTo(SubscriptionAccount::class);} }
